#!/usr/bin/env python3
"""Regenerates the Chapter-4 part of documentation/QUEST_DATABASE.md from the canonical data.

    python3 -P tools/docs/gen_quest_db_c4.py          (Windows: py -3 -P tools/docs/gen_quest_db_c4.py)
    python3 -P tools/docs/gen_quest_db_c4.py --check  (exit 1 if the document is not up to date; writes nothing)

Run tools/docs/gen_quest_db_c3.py first (it owns §1 FLOW — the whole scene chain incl. Chapter 4 — and §11).
Idempotent: only the text between these marker lines is rewritten (everything else is hand-written):
    <!-- C4:BEGIN (generated by tools/docs/gen_quest_db_c4.py) -->  …  <!-- C4:END -->   §12 Chapter 4 part 1
On the first run the block is appended at the end of the file.
Sources (read at run time): data/v3/*.json, data/chapters/c4.json (expressions, variants, reactions, puzzle UIs,
cinematic scenes, level files), data/locale/de_c4_{dialogue,ui,cinematics,characters}.json, the level files of the
Chapter-4 scenes (hotspot per objective). Binding design: documentation/C4_DESIGN.md. The helpers (text lookup,
condition rendering, fallback-only detection) are those of gen_quest_db_c3.py.
"""
import importlib.util
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
_spec = importlib.util.spec_from_file_location('gen_quest_db_c3', Path(__file__).resolve().parent / 'gen_quest_db_c3.py')
g3 = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(g3)

DOC = g3.DOC
GEN = 'tools/docs/gen_quest_db_c4.py'
BEGIN, END = '<!-- C4:BEGIN (generated by %s) -->' % GEN, '<!-- C4:END -->'
CH = g3.load('data/chapters/c4.json')
LOC = dict(g3.V3['locale_de']['strings'])
for f in ['de_c4_dialogue', 'de_c4_ui', 'de_c4_cinematics', 'de_c4_characters']:
    LOC.update(g3.load('data/locale/%s.json' % f)['strings'])
# the shared helpers read these module globals
g3.CH = CH
g3.LOC = LOC
QUESTS = g3.QUESTS
C4_QUESTS = [q for q in QUESTS if q['title_key'] == 'ui.chapter_c4' and q['scene'].startswith('L_C4_')]   # part 1 only (part 2: gen_quest_db_c4p2.py)
C4_SCENES = [q['scene'] for q in C4_QUESTS]
PUZZLE_UI = {'pz_c4_routes': 'ui.c4.routes', 'pz_c4_numbers': 'ui.c4.numbers'}
t, code, ids, table, when_text, effects_text = g3.t, g3.code, g3.ids, g3.table, g3.when_text, g3.effects_text


def hotspots():
    """objective id -> hotspot id of its interactable in the level file of each Chapter-4 scene"""
    out = {}
    for scene in C4_SCENES:
        path = ROOT / str(CH['levels'][scene]).replace('res://', '')
        if not path.exists():
            continue
        for block in path.read_text(encoding='utf-8').split('\n[node '):
            o = g3.re.search(r'^objective_id = "([^"]+)"', block, g3.re.M)
            h = g3.re.search(r'^hotspot_id = "([^"]+)"', block, g3.re.M)
            if o and h:
                out.setdefault(o.group(1), h.group(1))
    return out


def c4_block():
    hs = hotspots()
    title_key = C4_QUESTS[0]['title_key']
    out = ['## 12. Chapter 4, part 1 — „%s“ (Karsk and Berlin: the transport path and the archive path)' % t(title_key),
           '',
           'Binding design: `documentation/C4_DESIGN.md`. Everything in this section is generated from `data/v3`, '
           '`data/chapters/c4.json` and `data/locale/de_c4_*.json` by `%s`; edit the data, then re-run the script. The '
           'engine is unchanged: Chapter 4 part 1 is four more quests in the single scene chain, inserted between '
           '`L_C3_Quay` and the montage, alternating between Karsk (Alexei) and Berlin (Konrad). Two level files host '
           'two scenes each (`L_C4_Tunnels.tscn`: TunnelsA/B, `L_C4_Annex.tscn`: AnnexA/B); every scene change '
           'crosses a city and loads a level, the match-cut cinematics carry the protagonists between them. No new '
           'flag; the one decision writes an existing meter and the choice history.' % GEN, '']
    # 12.1 transitions
    out += ['### 12.1 Scene flow and transitions', '']
    rows = []
    for q in [q for q in QUESTS if q['scene'] in ['L_C3_Quay'] + C4_SCENES]:
        s = g3.SCENES[q['scene']]
        nxt = g3.SCENES[s['next_scene']]
        unlocks = [x['id'] for x in QUESTS if q['completion_event'] in x.get('requires_events', [])]
        rows.append([code(q['completion_event']), code(q['objectives'][-1]['id']),
                     ids(g3.cinematics_on('trigger_event', q['completion_event'])),
                     '%s (%s)' % (code(nxt['id']), code(nxt['protagonist'])), ids(unlocks) if unlocks else 'finale gate'])
    out += table(['Event', 'Fired by (last objective)', 'Queues (data order)', 'Scene → (protagonist)', 'Unlocks'], rows)
    out += ['', 'Level file per scene: ' + ', '.join('%s → %s' % (code(s), code(CH['levels'][s])) for s in C4_SCENES) +
            '. Each scene has its own entry spawn (' + ', '.join('%s %s' % (code(s), code(CH['entry_spawn'][s]))
                                                          for s in C4_SCENES) + ') and its own walk area.', '']
    # 12.2 quests
    out += ['### 12.2 Quests', '']
    out += table(['Quest', 'Title (de)', 'Character', 'Scene', 'Gate (`requires_events`)', 'Completion event'],
                 [[code(q['id']), '%s (%s)' % (t(q['title_key']), code(q['title_key'])), code(q['character']),
                   code(q['scene']), ids(q.get('requires_events', [])), code(q['completion_event'])] for q in C4_QUESTS])
    out.append('')
    # 12.3 objectives
    out += ['### 12.3 Objectives', '']
    for n, q in enumerate(C4_QUESTS, 1):
        scene = g3.SCENES[q['scene']]
        out += ['#### 12.3.%d %s — %s (%s)' % (n, code(q['id']), t(scene['title_key']), q['character'].capitalize()), '']
        sketch = ' ─> '.join(' + '.join(lv) for lv in g3.layers(q))
        out += ['```', sketch + ' ══> ' + q['completion_event'], '```', '']
        rows = []
        for o in q['objectives']:
            det = []
            if o['type'] == 'dialogue':
                dlg = g3.DIALOGUES[o['dialogue_id']]
                det.append('%s, %d nodes' % (code(dlg['id']), len(dlg['nodes'])))
                if o.get('grant_item'):
                    det.append('item at the terminal node')
            elif o['type'] == 'puzzle':
                det.append(code(o['puzzle_id']))
            elif o['type'] == 'choice':
                det.append(' / '.join(code(c['id']) for c in o['choices']))
            if o['id'] in hs:
                det.append('hotspot ' + code(hs[o['id']]))
            rows.append([code(o['id']), o['type'], t(o['text_key']), ids(o.get('requires', [])),
                         code(o['grant_item']) if o.get('grant_item') else '—',
                         'per choice (§12.8)' if o['type'] == 'choice' else effects_text(o.get('effects', {})),
                         '; '.join(det)])
        out += table(['Objective', 'Type', 'Objective text (de)', 'Requires', 'Grants', 'Effects', 'Details'], rows)
        out.append('')
    # 12.4 dialogues
    out += ['### 12.4 Dialogues', '',
            'Linear, one node per `advance_dialogue`; resumes at the saved node. *Expr* = portrait expression '
            '(`line_expr`); *Variants* replace the line text when their condition holds (first match wins); base lines '
            'whose variants cover every option of an earlier mandatory choice are *fallback only* (§11.4).', '']
    for q in C4_QUESTS:
        for o in q['objectives']:
            if o['type'] != 'dialogue':
                continue
            dlg = g3.DIALOGUES[o['dialogue_id']]
            extra = '; completing it grants %s' % code(o['grant_item']) if o.get('grant_item') else ''
            out += ['**%s** (objective %s, entry %s%s)' % (code(dlg['id']), code(o['id']), code(dlg['entry_node']), extra), '']
            rows = []
            for node in dlg['nodes']:
                var = ['%s: „%s“ (%s)' % (when_text(v.get('when')), t(v['key']), code(v['key']))
                       for v in CH.get('line_variants', {}).get(node['id'], [])]
                fb = g3.fallback_choice(node['id'], q, o)
                if fb:
                    var.append('*base line = fallback only: every option of %s is covered*' % code(fb))
                rows.append(['%s%s' % (code(node['id']), ' (end)' if node.get('end') else ''), node['speaker'],
                             CH.get('line_expr', {}).get(node['id'], 'neutral'), code(node['text_key']),
                             t(node['text_key']), '<br>'.join(var) if var else '—'])
            out += table(['Node', 'Speaker', 'Expr', 'Text key', 'Line (de)', 'Variants'], rows)
            out.append('')
    speakers = []
    for q in C4_QUESTS:
        for o in q['objectives']:
            if o['type'] == 'dialogue':
                for node in g3.DIALOGUES[o['dialogue_id']]['nodes']:
                    if node['speaker'] not in g3.PROTAGONISTS and node['speaker'] not in speakers:
                        speakers.append(node['speaker'])
    out += ['Journal „Personen“ (new speakers, in the order they are met): ' + ', '.join(
        '%s %s' % (code(s), t('sys.journal.person.%s.name' % s)) for s in speakers) + '.', '']
    # 12.5 puzzles
    out += ['### 12.5 Puzzles', '']
    puzzle_objs = [o for q in C4_QUESTS for o in q['objectives'] if o['type'] == 'puzzle']
    rows = []
    for o in puzzle_objs:
        p = g3.PUZZLES[o['puzzle_id']]
        rows.append([code(p['id']), code(o['id']), code(p['type']), ids(p['clue_item_ids']),
                     ', '.join(p.get('display_symbols', [])) or 'start pose 0/0/0',
                     code(json.dumps(p['solution'])), '%d failures' % p['hint_after_attempts'], p.get('world_note', '')])
    out += table(['Puzzle', 'Objective', 'Type', 'Clue items (must be owned)', 'Shown', 'Solution', 'Hint after', 'Notes'], rows)
    for o in puzzle_objs:
        p = g3.PUZZLES[o['puzzle_id']]
        pre = PUZZLE_UI[p['id']]
        plates = [(sym, LOC.get(pre + '.card.' + sym), LOC.get(pre + '.under.' + sym)) for sym in p.get('display_symbols', [])]
        out += ['']
        if plates:
            out += ['%s plates (face / under the paint): ' % code(p['id']) +
                    ', '.join('%s „%s“ / „%s“' % (code(s), n, u) for s, n, u in plates) + '.']
        out += ['%s title „%s“. Hint (`%s.hint`): „%s“' % (code(p['id']), t(pre + '.title'), pre, t(pre + '.hint')),
                'Success (`%s.success`): „%s“' % (pre, t(pre + '.success')),
                'UI scene: %s (`open(obj_id)`, signal `solved`; key contract C4_DESIGN §2.7).' %
                code(CH.get('puzzles', {}).get(o['id'], '—'))]
    out += ['', 'Engine semantics as in §4: unlimited retries, no penalty; a wrong list / pose counts one attempt, a '
            'malformed answer is rejected and not counted.', '']
    # 12.6 evidence
    out += ['### 12.6 Evidence', '']
    grant = {o['grant_item']: o['id'] for q in QUESTS for o in q['objectives'] if o.get('grant_item')}
    out += table(['Item', 'Name (de)', 'Description (de)', 'Category', 'Scene', 'Granted by'],
                 [[code(i['id']), t(i['name_key']), t(i['description_key']), i['category'], code(i['scene']),
                   code(grant.get(i['id'], '—'))] for i in g3.V3['items']['items'] if i['scene'] in C4_SCENES])
    out += ['', 'Granted once, in acquisition order, after the 22 items of the slice and Chapter 3.', '']
    # 12.7 flags and events
    out += ['### 12.7 Flags and events', '']
    c4_objs = {o['id'] for q in C4_QUESTS for o in q['objectives']}
    rows = []
    for q in C4_QUESTS:
        for o in q['objectives']:
            for c in o.get('choices', []):
                for f, spec in c.get('effects', {}).items():
                    meta = g3.FLAGS[f]
                    rows.append([code(f), meta['type'], str(meta['default']).lower(), '%d–%d' % (meta['min'], meta['max']),
                                 code('%s = %s' % (o['id'], c['id'])) + ' (%+d)' % spec['delta']])
    out += table(['Flag', 'Type', 'Default', 'Range', 'Changed by'], rows)
    out += ['', 'Events: ' + ids([q['completion_event'] for q in C4_QUESTS]) + ' (before `slice_completed`). No new flag '
            '(C4_DESIGN §1.1); `witnesses_exposed` and `marta_trust` stay derivable from `choice_history.c4d_choose`, '
            '`people_protected` became a flag in part 2 after the save migration (§13.7).', '']
    reads = {}
    for node, vs in CH.get('line_variants', {}).items():
        for v in vs:
            for f in (v.get('when') or {}):
                reads.setdefault(f, []).append('line ' + code(node))
    for obj, table_ in CH.get('choice_text', {}).items():
        for cid, vs in table_.items():
            for v in vs:
                for f in (v.get('when') or {}):
                    reads.setdefault(f, []).append('option ' + code(cid))
    out += ['Presentation conditions (`data/chapters/c4.json`, first match wins) — how the earlier decisions reach '
            'Chapter 4:', '']
    out += table(['Condition read', 'Used by'], [[code(f), ', '.join(dict.fromkeys(reads[f]))] for f in g3.FLAGS if f in reads]
                 + [[code(f), ', '.join(dict.fromkeys(reads[f]))] for f in sorted(reads) if f.startswith(g3.CHOICE_PREFIX)])
    out.append('')
    # 12.8 choices
    out += ['### 12.8 Choices and reactions', '']
    rows = []
    for q in C4_QUESTS:
        for o in q['objectives']:
            if o['type'] != 'choice':
                continue
            for n, c in enumerate(o['choices']):
                var = ['%s: „%s“' % (when_text(v.get('when')), t(v['key']))
                       for v in CH.get('choice_text', {}).get(o['id'], {}).get(c['id'], [])]
                rea = ['%s (%s): „%s“ (%s)' % (v['speaker'], v.get('expr', 'neutral'), t(v['key']), code(v['key']))
                       for v in CH.get('reactions', {}).get(o['id'], {}).get(c['id'], [])]
                rows.append(['%s „%s“' % (code(o['id']), t(o['text_key'])) if n == 0 else '', code(c['id']),
                             t(c['text_key']), effects_text(c.get('effects', {})), '<br>'.join(var) if var else '—',
                             '<br>'.join(rea) if rea else '—'])
    out += table(['Objective', 'Choice id', 'Text (de)', 'Effect', 'Option text variants', 'Reaction'], rows)
    out += ['', 'The end card lists every decision of the playthrough in story order (seven after Chapter 4 part 1, eight after part 2).', '']
    # 12.9 cinematics
    out += ['### 12.9 Cinematics', '']
    rows = []
    for s in g3.SEQUENCES:
        if s['id'] not in CH.get('cinematics', {}):
            continue
        trig = ('event ' + code(s['trigger_event'])) if s.get('trigger_event') else ('objective ' + code(s['trigger_objective']))
        shots = ', '.join('%s %s (%s s)' % (x['id'], x['shot'], x['duration_s']) for x in s['shots'])
        rows.append([code(s['id']), trig, code(s['skip_policy']), shots, code(CH['cinematics'][s['id']])])
    out += table(['Sequence', 'Trigger', 'Skip policy (data)', 'Shots', 'Scene (§12.5)'], rows)
    out += ['', 'Queued once in data order (`LS_C4_Homeward` right after `LS_C3_Halves`, both on `c3g_completed`); '
            'skipping has no story effect. Inner lines and captions (`data/locale/de_c4_cinematics.json`):', '']
    out += table(['Key', 'Line (de)'], [[code(k), v] for k, v in LOC.items() if k.startswith('cin.c4.')])
    out.append('')
    # 12.10 people
    people = [k[len('char.'):-len('.name')] for k in g3.load('data/locale/de_c4_characters.json')['strings']
              if k.startswith('char.') and k.endswith('.name')]
    out += ['### 12.10 People of the chapter', '']
    out += table(['Id', 'Name', 'Role', 'Journal note'],
                 [[code(p), t('char.%s.name' % p), t('char.%s.role' % p),
                   LOC.get('sys.journal.person.%s.note' % p, '—')] for p in people])
    out += ['', 'Existing characters in the chapter: `alexei`, `konrad`, `guard` (annex door), `berlin_child` (Ilse, '
            'life strip), `clerk` (typists, life strips).', '']
    return out


def render(text, lines):
    body = BEGIN + '\n' + '\n'.join(lines).rstrip('\n') + '\n' + END
    if BEGIN in text:
        if text.count(BEGIN) != 1 or text.count(END) != 1 or text.index(END) < text.index(BEGIN):
            raise SystemExit('%s: malformed C4 markers' % DOC)
        i, j = text.index(BEGIN), text.index(END) + len(END)
        return text[:i] + body + text[j:]
    return text.rstrip('\n') + '\n\n---\n\n' + body + '\n'


def main():
    text = DOC.read_text(encoding='utf-8')
    new = render(text, c4_block())
    if '--check' in sys.argv:
        if new != text:
            print('%s is out of date — run %s' % (DOC.relative_to(ROOT), GEN))
            sys.exit(1)
        print('up to date')
        return
    if new != text:
        DOC.write_text(new, encoding='utf-8', newline='\n')
        print('updated %s' % DOC.relative_to(ROOT))
    else:
        print('%s already up to date' % DOC.relative_to(ROOT))


if __name__ == '__main__':
    main()
